import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { InjectorResistorPage } from './injector-resistor.page';

const routes: Routes = [
  {
    path: '',
    component: InjectorResistorPage
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class InjectorResistorPageRoutingModule {}
